func getDiffCves(previous, current models.ScanResult, plus, minus bool) models.VulnInfos {
	changes := models.VulnInfos{}
	if plus {
		for id, vuln := range current.ScannedCves {
			if _, exists := previous.ScannedCves[id]; !exists {
				vuln.DiffStatus = models.DiffPlus
				changes[id] = vuln
			}
		}
	}
	if minus {
		for id, vuln := range previous.ScannedCves {
			if _, exists := current.ScannedCves[id]; !exists {
				vuln.DiffStatus = models.DiffMinus
				changes[id] = vuln
			}
		}
	}
	if len(changes) == 0 {
		util.Log.Infof("%s: There are %d vulnerabilities, but no difference between current result and previous one.", current.FormatServerName(), len(current.ScannedCves))
	}
	return changes
}

func isCveFixed(current models.VulnInfo, previous models.ScanResult) bool {
	preVinfo, _ := previous.ScannedCves[current.CveID]
	pre := map[string]bool{}
	for _, h := range preVinfo.AffectedPackages {
		pre[h.Name] = h.NotFixedYet
	}

	cur := map[string]bool{}
	for _, h := range current.AffectedPackages {
		cur[h.Name] = h.NotFixedYet
	}

	return !reflect.DeepEqual(pre, cur)
}

