// FormatTextReportHeader returns header of text report
func (r ScanResult) FormatTextReportHeader() string {
	var buf bytes.Buffer
	for i := 0; i < len(r.ServerInfo()); i++ {
		buf.WriteString("=")
	}

	pkgs := r.FormatUpdatablePacksSummary()
	if 0 < len(r.WordPressPackages) {
		pkgs = fmt.Sprintf("%s, %d WordPress pkgs", pkgs, len(r.WordPressPackages))
	}
	if 0 < len(r.LibraryScanners) {
		pkgs = fmt.Sprintf("%s, %d libs", pkgs, r.LibraryScanners.Total())
	}

	return fmt.Sprintf("%s\n%s\n%s, %s, %s, %s, %s\n%s\n",
		r.ServerInfo(),
		buf.String(),
		r.ScannedCves.FormatCveSummary(),
		r.ScannedCves.FormatFixedStatus(r.Packages),
		r.FormatExploitCveSummary(),
		r.FormatMetasploitCveSummary(),
		r.FormatAlertSummary(),
		pkgs)
}

// FormatUpdatablePacksSummary returns a summary of updatable packages
func (r ScanResult) FormatUpdatablePacksSummary() string {
	if !r.isDisplayUpdatableNum() {
		return fmt.Sprintf("%d installed", len(r.Packages))
	}

	nUpdatable := 0
	for _, p := range r.Packages {
		if p.NewVersion == "" {
			continue
		}
		if p.Version != p.NewVersion || p.Release != p.NewRelease {
			nUpdatable++
		}
	}
	return fmt.Sprintf("%d installed, %d updatable",
		len(r.Packages),
		nUpdatable)
}

// FormatExploitCveSummary returns a summary of exploit cve
func (r ScanResult) FormatExploitCveSummary() string {
	nExploitCve := 0
	for _, vuln := range r.ScannedCves {
		if 0 < len(vuln.Exploits) {
			"edited": {CveID: "edited", CpeURIs: []string{"changed"}},
		},
		Packages: models.Packages{"new-package": {Name: "new-package", Version: "current"}},
	}}
	previous := models.ScanResults{{
		ServerName: "host",
		ScannedCves: models.VulnInfos{
			"old":    {CveID: "old", AffectedPackages: models.PackageFixStatuses{{Name: "old-package"}}},
			"same":   {CveID: "same"},
			"edited": {CveID: "edited"},
		},
		Packages: models.Packages{"old-package": {Name: "old-package", Version: "previous"}},
	}}
	for _, tc := range []struct {
		name        string
		plus, minus bool
		want        models.VulnInfos
	}{
		{"plus", true, false, models.VulnInfos{"new": {CveID: "new", DiffStatus: models.DiffPlus, AffectedPackages: models.PackageFixStatuses{{Name: "new-package"}}}}},
		{"minus", false, true, models.VulnInfos{"old": {CveID: "old", DiffStatus: models.DiffMinus, AffectedPackages: models.PackageFixStatuses{{Name: "old-package"}}}}},
		{"both", true, true, models.VulnInfos{
			"new": {CveID: "new", DiffStatus: models.DiffPlus, AffectedPackages: models.PackageFixStatuses{{Name: "new-package"}}},
			"old": {CveID: "old", DiffStatus: models.DiffMinus, AffectedPackages: models.PackageFixStatuses{{Name: "old-package"}}},
		}},
		{"neither", false, false, models.VulnInfos{}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			results, err := diff(current, previous, tc.plus, tc.minus)
			if err != nil {
				t.Fatal(err)
			}
			got := results[0]
			if !reflect.DeepEqual(got.ScannedCves, tc.want) {
				t.Errorf("CVEs = %v, want %v", got.ScannedCves, tc.want)
			}
			if tc.plus && got.Packages["new-package"].Version != "current" {
				t.Errorf("new package must come from current scan: %v", got.Packages["new-package"])
			}
			if tc.minus && got.Packages["old-package"].Version != "previous" {
				t.Errorf("resolved package must come from previous scan: %v", got.Packages["old-package"])
			}
		})
	}
}

